    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    book_id uuid NOT NULL,
    fiscal_year_id uuid NOT NULL,
    period_no smallint NOT NULL,
    name text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid
);

-- @seq 757
CREATE TABLE public.acct_recurring_journals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    book_id uuid NOT NULL,
    name text NOT NULL,
    frequency text NOT NULL,
    interval_n integer DEFAULT 1 NOT NULL,
    next_run_date date NOT NULL,
    end_date date,
    active boolean DEFAULT true NOT NULL,
    template jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_run_at timestamp with time zone
);

-- @seq 760
CREATE TABLE public.acct_report_packages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    sections text[] DEFAULT ARRAY['profit_and_loss'::text, 'balance_sheet'::text, 'cash_flow'::text, 'trial_balance'::text, 'kpis'::text, 'flux'::text] NOT NULL,
    flux_amount_threshold numeric DEFAULT 500 NOT NULL,
    flux_pct_threshold numeric DEFAULT 0.10 NOT NULL,
    recipients text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT acct_report_packages_sections_chk CHECK ((sections <@ ARRAY['profit_and_loss'::text, 'balance_sheet'::text, 'cash_flow'::text, 'trial_balance'::text, 'kpis'::text, 'flux'::text, 'close_status'::text, 'ar_aging'::text, 'ap_aging'::text]))
);

-- @seq 761
CREATE TABLE public.acct_report_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    package_id uuid,
    title text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    contents jsonb NOT NULL,
    commentary text,
    published_by uuid,
    published_at timestamp with time zone DEFAULT now() NOT NULL
);

-- @seq 765
CREATE TABLE public.acct_review_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    finding_id uuid NOT NULL,
    author_id uuid,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

-- @seq 766
CREATE TABLE public.acct_review_findings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    first_run_id uuid,
    last_run_id uuid,
    check_code text NOT NULL,
    severity text NOT NULL,
    title text NOT NULL,
    detail text,
    source_type text,
    source_id uuid,
    journal_entry_id uuid,
    account_id uuid,
    amount numeric(24,6),
    txn_date date,
    fingerprint text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    assignee_id uuid,
    resolution_note text,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT acct_review_findings_severity_check CHECK ((severity = ANY (ARRAY['error'::text, 'warning'::text, 'info'::text]))),
    CONSTRAINT acct_review_findings_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'resolved'::text, 'ignored'::text])))
);

