CREATE TABLE public.acct_review_ignore_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    check_code text NOT NULL,
    account_id uuid,
    source_id uuid,
    title_contains text,
    reason text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

-- @seq 768
CREATE TABLE public.acct_review_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    entity_id uuid,
    period_from date NOT NULL,
    period_to date NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    finding_count integer DEFAULT 0 NOT NULL,
    new_count integer DEFAULT 0 NOT NULL,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    run_by uuid,
    run_at timestamp with time zone DEFAULT now() NOT NULL
);

-- @seq 786
CREATE TABLE public.acct_transaction_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    entity_id uuid,
    name text NOT NULL,
    description text,
    memo text,
    lines jsonb NOT NULL,
    parameters jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_adjusting boolean DEFAULT false NOT NULL,
    auto_reverse boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT acct_transaction_templates_lines_check CHECK (((jsonb_typeof(lines) = 'array'::text) AND (jsonb_array_length(lines) >= 2)))
);

